class Solution:
    def getHappyString(self, n: int, k: int) -> str:
        total = 3 * (1 << (n - 1))
        if k > total:
            return ""
        k -= 1
        first_char_idx = k // (1 << (n - 1))
        res = [["a", "b", "c"][first_char_idx]]
        k %= (1 << (n - 1))
        for i in range(1, n):
            options = [c for c in ["a", "b", "c"] if c != res[-1]]
            branch_size = 1 << (n - 1 - i)
            choice = k // branch_size
            res.append(options[choice])
            k %= branch_size
        return "".join(res)

#include <string>
#include <vector>

class Solution {
public:
    std::string getHappyString(int n, int k) {
        int total = 3 * (1 << (n - 1));
        if (k > total) return "";
        k--;
        std::string res = "";
        std::vector<char> allChars = {'a', 'b', 'c'};
        res += allChars[k / (1 << (n - 1))];
        k %= (1 << (n - 1));
        for (int i = 1; i < n; ++i) {
            std::vector<char> options;
            for (char c : allChars) if (c != res.back()) options.push_back(c);
            int branchSize = 1 << (n - 1 - i);
            res += options[k / branchSize];
            k %= branchSize;
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String getHappyString(int n, int k) {
        int total = 3 * (1 << (n - 1));
        if (k > total) return "";
        k--;
        StringBuilder res = new StringBuilder();
        char[] allChars = {'a', 'b', 'c'};
        res.append(allChars[k / (1 << (n - 1))]);
        k %= (1 << (n - 1));
        for (int i = 1; i < n; i++) {
            List<Character> options = new ArrayList<>();
            for (char c : allChars) if (c != res.charAt(res.length() - 1)) options.add(c);
            int branchSize = 1 << (n - 1 - i);
            res.append(options.get(k / branchSize));
            k %= branchSize;
        }
        return res.toString();
    }
}

var getHappyString = function(n, k) {
    const total = 3 * (1 << (n - 1));
    if (k > total) return "";
    k--;
    const allChars = ['a', 'b', 'c'];
    const res = [allChars[Math.floor(k / (1 << (n - 1)))]];
    k %= (1 << (n - 1));
    for (let i = 1; i < n; i++) {
        const options = allChars.filter(c => c !== res[res.length - 1]);
        const branchSize = 1 << (n - 1 - i);
        res.push(options[Math.floor(k / branchSize)]);
        k %= branchSize;
    }
    return res.join('');
};
